import hmac
import json

from payhook.errors import InvalidNotification


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    # Validate and parse timestamp
    timestamp_header = headers.get("X-Pay-Timestamp")
    if not timestamp_header:
        raise InvalidNotification("Missing X-Pay-Timestamp header")
    try:
        timestamp = int(timestamp_header)
    except (ValueError, TypeError):
        raise InvalidNotification("Malformed X-Pay-Timestamp header")

    # Check timestamp is within 300 seconds of now
    if abs(timestamp - now) > 300:
        raise InvalidNotification("Timestamp outside acceptable window")

    # Validate signature
    sig_header = headers.get("X-Pay-Signature")
    if not sig_header or not sig_header.startswith("v1="):
        raise InvalidNotification("Missing or malformed X-Pay-Signature header")
    provided_digest = sig_header[3:]
    expected_digest = hmac.new(
        secret,
        timestamp_header.encode("ascii") + b"." + raw_body,
        hashlib.sha256
    ).hexdigest()
    if not hmac.compare_digest(provided_digest, expected_digest):
        raise InvalidNotification("Signature verification failed")

    # Parse JSON body
    try:
        data = json.loads(raw_body.decode("utf-8"))
    except (json.JSONDecodeError, UnicodeDecodeError):
        raise InvalidNotification("Malformed JSON body")

    if not isinstance(data, dict):
        raise InvalidNotification("JSON body must be an object")

    # Validate event_id
    event_id = data.get("event_id")
    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification("Missing or invalid event_id")

    # Validate account_id
    account_id = data.get("account_id")
    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification("Missing or invalid account_id")

    # Validate amount_minor (must be int, not bool, and nonnegative)
    amount_minor = data.get("amount_minor")
    if isinstance(amount_minor, bool) or not isinstance(amount_minor, int):
        raise InvalidNotification("Invalid amount_minor")
    if amount_minor < 0:
        raise InvalidNotification("amount_minor must be nonnegative")

    # Validate currency (three uppercase ASCII letters)
    currency = data.get("currency")
    if not isinstance(currency, str) or len(currency) != 3:
        raise InvalidNotification("Invalid currency")
    if not currency.isascii() or not currency.isupper():
        raise InvalidNotification("Invalid currency")

    return {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount_minor,
        "currency": currency,
    }"}]}
